    "codigo_interno": "570",
    "nombre": "NIVELES PLASMÁTICOS DE VANCOMICINA",
    "nombres_examen": "Niveles plasmáticos de Vancomicina",
    "sinonimos": [],
    "area": "Plazo de Entrega Laboratorio Días de Procesamiento de Resultados",
